## ALL PEERS (inside CraftSystem's event, the same order and float code everywhere): piece `pid` gave away all but `left` m³ of
## itself. A stone shrinks by uniform scale about its centroid (its mesh is centred there), a wood piece is sawn short along its
## length (Rod.keep_for / Rod.part: exact by Rod.vol); the foliage of a branch rides with what is left. `left` <= GONE_M3: the
## piece is used up and leaves its bag. The same piece id stays, so the Bag needs no room for it. Returns the m³ given away.
func apply_left(pid: int, left: float) -> float:
	var rec: Dictionary = held.get(pid, {})
	if rec.is_empty():
		return 0.0
	var old := float(rec.vol)
	var mine := int(rec.peer) == multiplayer.get_unique_id()
	if left <= GONE_M3:
		held.erase(pid)
		if mine:
			Bag.remove_piece(pid)
		return old
	left = minf(left, old)
	if rec.has("mesh"):
		rec.mesh = StoneMesh.scaled(rec.mesh as CpuMesh, pow(left / old, 1.0 / 3.0))
	else:
		var rod: Dictionary = rec.rod
		var cut := Rod.keep_for(rod, Rod.vol(rod) - left)
		rec.rod = Rod.part(rod, 0.0, cut)
	rec.vol = left
	if mine:
		Bag.set_piece(pid, left, _bag_piece(rec))
	return old - left


## ALL PEERS: a new piece record (the dismantle event, same arguments everywhere -> the same shape): `vol` m³ of `mat`.
## "chunk" / "ingot": a block 1 : 0.8 : 0.6 centred on its centroid (exact volume), a stone of the world's system;
## "piece": a straight rod of length `len` (frustum r0 = r1: exact volume), a Timber when dropped.
static func make_record(pid: int, peer: int, mat: String, form: String, vol: float, len := 0.5) -> Dictionary:
	var rec := {id = pid, peer = peer, mat = mat, form = form, vol = vol, foliage = 0.0}
	if form == "piece":
		var r := sqrt(vol / (PI * len))
		rec.src = "timber"
		rec.rod = Rod.make(Transform3D.IDENTITY, len, r, r)
	else:
		rec.src = "stone"
		rec.mesh = _block(mat, vol)
		rec.bed = Vector3.ZERO
	return rec


